const API_BASE = window.API_BASE || 'http://127.0.0.1:8000';
const state = { view:'landing', citizen:JSON.parse(localStorage.getItem('rr_citizen')||'null'), authority:false, reports:[], citizens:[], upload:null, filters:{status:'all'}, authMode:'login', authRole:'citizen', language:'en', translations:null };
const $ = (s, root=document) => root.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const icon = name => ({home:'▦',report:'+',track:'⌕',people:'••',chart:'▥',arrow:'↗',upload:'↑',check:'✓',close:'×',pin:'⌖'}[name] || '•');
function toast(message){const n=document.createElement('div');n.className='toast';n.textContent=message;$('#toast-region').appendChild(n);setTimeout(()=>n.remove(),3600)}
async function api(path, options={}){const res=await fetch(`${API_BASE}${path}`,options);let data={};try{data=await res.json()}catch{}if(!res.ok)throw new Error(data.detail||'Something went wrong.');return data}
function mediaUrl(url){return url?(url.startsWith('http')?url:`${API_BASE}${url}`):''}
function formatDate(v){return v?new Date(v).toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'}):'—'}
function severity(score){const n=Number(score||0);return {label:n>=.7?'High':n>=.45?'Medium':'Low',class:n>=.7?'high':n>=.45?'medium':'low',value:Math.round(n*100)}}
function layout(content, role){return `<div class="app-layout"><aside class="rail"><div class="brand"><span class="brand-mark"></span>Road-Ranger</div><nav class="rail-nav"><div class="nav-label micro">Workspace</div>${role==='citizen'?`<button class="nav-btn ${state.view==='citizen'?'active':''}" data-view="citizen"><span class="nav-icon">${icon('home')}</span>Overview</button><button class="nav-btn ${state.view==='report'?'active':''}" data-view="report"><span class="nav-icon">${icon('report')}</span>Report issue</button><button class="nav-btn ${state.view==='track'?'active':''}" data-view="track"><span class="nav-icon">${icon('track')}</span>Track reports</button>`:`<button class="nav-btn ${state.view==='authority'?'active':''}" data-view="authority"><span class="nav-icon">${icon('home')}</span>Dashboard</button><button class="nav-btn ${state.view==='reports'?'active':''}" data-view="reports"><span class="nav-icon">${icon('report')}</span>Reports queue</button><button class="nav-btn ${state.view==='citizens'?'active':''}" data-view="citizens"><span class="nav-icon">${icon('people')}</span>Citizens</button>`}</nav><div class="rail-bottom"><button class="button ghost small" style="color:#fff;border-color:#424942;width:100%;margin-bottom:14px" data-action="toggle-language">${state.language==='en'?'Manipuri · মৈতৈলোন্':'English'}</button><div class="micro">Connected system</div><div style="margin-top:6px;font-size:12px">FastAPI · online</div></div></aside><main class="workspace">${content}</main></div>`}
function landing(){return `<div class="landing"><header class="topbar"><div class="brand"><span class="brand-mark"></span>Road-Ranger</div><span class="micro">Public works / Manipur</span></header><main class="landing-main"><div class="kicker"><span class="dot"></span>Road intelligence desk</div><h1>Make every road issue visible.</h1><p class="lede">A clear line from citizen reports to accountable action. Choose your workspace to continue.</p><div class="role-grid"><button class="role-card" data-view="citizen"><div><div class="micro">For residents</div><h2>Citizen desk</h2><p>Report damage, share its location, and follow the repair trail from one calm workspace.</p></div><div class="role-footer"><span class="button">Open citizen desk <span>${icon('arrow')}</span></span><span class="arrow">${icon('report')}</span></div></button><button class="role-card dark" data-view="authority"><div><div class="micro">For public works</div><h2>Authority desk</h2><p>Prioritize incoming reports, inspect evidence, and close the loop with communities.</p></div><div class="role-footer"><span class="button soft">Open authority desk <span>${icon('arrow')}</span></span><span class="arrow">${icon('chart')}</span></div></button></div></main><footer class="split"><span class="micro">Built for faster, safer streets</span><span class="micro">v1.1 / live service</span></footer></div>`}
function pagebar(title,subtitle,actions=''){return `<div class="pagebar"><div><h1 class="page-title">${title}</h1><p class="page-subtitle">${subtitle}</p></div><div class="page-actions">${actions}<button class="button ghost small" data-view="landing">Exit</button></div></div>`}
function authView(role){const citizen=role==='citizen';return `<div class="landing"><header class="topbar"><div class="brand"><span class="brand-mark"></span>Road-Ranger</div><button class="button ghost small" data-view="landing">Back</button></header><main class="landing-main" style="max-width:560px;padding-top:7vh"><div class="kicker"><span class="dot"></span>${citizen?'Citizen access':'Authority access'}</div><h1 style="font-size:clamp(46px,7vw,78px)">${citizen?(state.authMode==='login'?'Sign in to report.':'Create your citizen profile.'):'Authority sign in.'}</h1><p class="lede" style="font-size:15px;margin-bottom:28px">${citizen?'Your phone, profile, impact points, and report history stay linked to your account.':'Use the official PWD demo credentials to open the review desk.'}</p><section class="panel"><div class="segmented" style="margin-bottom:22px"><button class="${state.authMode==='login'?'active':''}" data-auth-mode="login">${citizen?'Sign in':'Officer sign in'}</button>${citizen?'<button class="'+(state.authMode==='register'?'active':'')+'" data-auth-mode="register">Register</button>':''}</div><form id="auth-form" class="form-grid">${citizen&&state.authMode==='register'?`<div class="field full"><label>Full name</label><input id="auth-name" required placeholder="Your name" /></div><div class="field full"><label>Mobile number</label><input id="auth-phone" required placeholder="+91 98765 43210" /></div><div class="field"><label>Username</label><input id="auth-username" required placeholder="yourname" /></div><div class="field"><label>Password</label><input id="auth-password" type="password" required minlength="6" placeholder="At least 6 characters" /></div><div class="field full"><label>One-time password</label><div class="split"><input id="auth-otp" placeholder="Use 123456 for demo" /><button class="button ghost small" type="button" data-action="send-otp">Send OTP</button></div></div>`:citizen?`<div class="field full"><label>Username</label><input id="auth-username" required placeholder="yourname" /></div><div class="field full"><label>Password</label><input id="auth-password" type="password" required placeholder="Your password" /></div>`:`<div class="field full"><label>Official gov email</label><input id="auth-email" type="email" required value="officer@pwd.gov.in" /></div><div class="field full"><label>Password</label><input id="auth-password" type="password" required value="GovSecure#2026" /></div><div class="field full"><label>Officer badge or OTP</label><input id="auth-badge" required value="PWD-MN-4091" /></div>`}<button class="button green full" type="submit">${citizen?(state.authMode==='login'?'Sign in':'Create account'):'Open authority desk'} ${icon('arrow')}</button></form><p class="muted" style="font-size:12px;margin:18px 0 0">${citizen&&state.authMode==='register'?'Demo OTP: 123456. Your mobile number and name will be saved to your profile.':!citizen?'Demo: officer@pwd.gov.in · GovSecure#2026 · PWD-MN-4091':''}</p></section></main></div>`}
function reportRows(reports,authority=false){if(!reports.length)return '<div class="empty">No reports match this view.</div>';return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Ticket</th><th>Evidence / issue</th>${authority?'<th>Location</th><th>Reporter</th>':''}<th>Severity</th><th>Status</th><th></th></tr></thead><tbody>${reports.map(r=>{const s=severity(r.severity_score);const thumb=r.image_url?`<img class="report-thumb" src="${mediaUrl(r.image_url)}" alt="${esc(r.damage_type)} evidence" data-action="detail" data-id="${r.id}" onerror="this.classList.add('broken')"/>`:'<div class="thumb-empty">No image</div>';const statusButton=authority?`<button class="button ${r.status==='addressed'?'ghost':'green'} small" data-action="toggle-address" data-id="${r.id}">${r.status==='addressed'?'↶ Reopen':'✓ Address'}</button>`:`<button class="button ghost small" data-action="detail" data-id="${r.id}">View</button>`;return `<tr><td><strong>#PWD-RR-${r.id}</strong><div class="muted">${formatDate(r.created_at)}</div></td><td><div class="evidence-cell">${thumb}<div><strong>${esc(r.damage_type)}</strong><div class="muted">${esc((r.description||'No description').slice(0,42))}</div></div></div></td>${authority?`<td><a href="https://www.google.com/maps?q=${encodeURIComponent(`${r.latitude},${r.longitude}`)}" target="_blank" rel="noopener" title="Open location in map">${icon('pin')} ${Number(r.latitude).toFixed(5)}, ${Number(r.longitude).toFixed(5)}</a></td><td>${esc(r.citizen_name||'Anonymous citizen')}</td>`:''}<td><span class="status ${s.class}">${s.label} · ${s.value}%</span></td><td><span class="status ${r.status==='addressed'?'addressed':'reported'}">${r.status==='addressed'?'Addressed':'Reported'}</span></td><td>${authority?`${statusButton} <button class="button ghost small" data-action="delete-report" data-id="${r.id}" title="Delete request">Delete</button> <button class="button ghost small" data-action="detail" data-id="${r.id}">View</button>`:statusButton}</td></tr>`}).join('')}</tbody></table></div>`}
async function loadReports(){try{state.reports=await api('/api/reports?deduplicate=true')}catch(e){toast(e.message)}}
function citizenHome(){if(!state.citizen)return authView('citizen');const reports=state.reports.filter(r=>r.user_id===state.citizen.id);return layout(`${pagebar('Citizen desk','A simple place to report, track, and contribute.','<button class="button green" data-view="report">'+icon('report')+' Report issue</button>')}<div class="metric-grid"><div class="metric"><div class="micro">Impact points</div><div class="value">${state.citizen.total_rewards||0}</div><div class="trend">+50 on every report</div></div><div class="metric"><div class="micro">Your reports</div><div class="value">${reports.length}</div><div class="trend">Keep your community moving</div></div><div class="metric"><div class="micro">Addressed</div><div class="value">${reports.filter(r=>r.status==='addressed').length}</div><div class="trend">Visible progress</div></div><div class="metric"><div class="micro">System status</div><div class="value" style="font-size:24px">Online</div><div class="trend">API synced just now</div></div></div><div class="content-grid"><section class="panel"><div class="panel-head"><h2 class="panel-title">Your report activity</h2><button class="button ghost small" data-view="track">View all ${icon('arrow')}</button></div>${reportRows(reports.slice(0,5))}</section><aside class="stack"><section class="panel"><div class="panel-head"><h2 class="panel-title">Your account</h2><span class="micro">Saved profile</span></div><div class="profile-row"><img class="avatar" src="${mediaUrl(state.citizen.profile_pic_url)}" onerror="this.style.display='none'"/><div><strong>${esc(state.citizen.name||state.citizen.username)}</strong><span>@${esc(state.citizen.username)}</span></div></div><div style="margin-top:22px" class="stack"><div class="split"><span class="muted">Mobile</span><strong>${esc(state.citizen.phone_number||'—')}</strong></div><div class="split"><span class="muted">Member since</span><strong>${formatDate(state.citizen.created_at)}</strong></div></div></section><section class="panel"><div class="panel-head"><h2 class="panel-title">Your profile is saved</h2></div><p class="muted">Your name, mobile number, rewards, and report history are linked to this account.</p><button class="button ghost small" data-action="logout">Sign out</button></section></aside></div>`, 'citizen')}
function reportForm(){return layout(`${pagebar('Report an issue','Give the public works team enough signal to act.')}<section class="panel" style="max-width:900px"><div class="panel-head"><div><h2 class="panel-title">New road damage report</h2><p class="muted">Your signed-in profile will be attached to this report.</p></div><span class="status low">+50 impact points</span></div><form id="report-form" class="form-grid"><div class="field"><label for="damage_type">Issue type</label><select id="damage_type" required><option>Pothole</option><option>Road Surface Crack</option><option>Drainage System Failure</option><option>Soil Erosion / Edge Collapse</option><option>Other</option></select></div><div class="field"><label for="location">Location coordinates</label><div class="split"><input id="location" placeholder="e.g. 24.8170, 93.9368" required/><button class="button ghost small" type="button" data-action="locate">${icon('pin')} Use GPS</button></div></div><div class="field full"><label for="description">What should the team know? <span class="muted">(250 characters)</span></label><textarea id="description" maxlength="250" placeholder="Add a nearby landmark or safety detail."></textarea></div><div class="field full"><div class="upload-zone"><input id="media" type="file" accept=".jpg,.jpeg,.png,.webp,.mp4,.mov,.avi"/><label for="media"><strong>${icon('upload')} Add photo or video</strong><br><span class="muted">The authority desk will see this evidence on the ticket.</span></label><div id="upload-preview"></div></div></div><div class="field full"><div class="split"><span class="muted">GPS permission is requested when this form opens.</span><button class="button green" type="submit">Submit report ${icon('arrow')}</button></div></div></form></section>`, 'citizen')}
function trackView(){return layout(`${pagebar('Track reports','Your report history and public works responses.','<button class="button green" data-view="report">'+icon('report')+' New report</button>')}<section class="panel"><div class="panel-head"><h2 class="panel-title">Report history</h2><span class="micro">${state.reports.filter(r=>r.user_id===state.citizen?.id).length} reports</span></div>${reportRows(state.reports.filter(r=>r.user_id===state.citizen?.id))}</section>`, 'citizen')}
function authorityHome(){const high=state.reports.filter(r=>Number(r.severity_score)>=.7).length,addressed=state.reports.filter(r=>r.status==='addressed').length;return layout(`${pagebar('Authority dashboard','A clear view of incoming road intelligence.','<button class="button ghost" data-view="reports">View queue '+icon('arrow')+'</button>')}<div class="metric-grid"><div class="metric"><div class="micro">Open reports</div><div class="value">${state.reports.filter(r=>r.status!=='addressed').length}</div><div class="trend">Requires review</div></div><div class="metric"><div class="micro">High severity</div><div class="value">${high}</div><div class="trend" style="color:var(--red)">Priority queue</div></div><div class="metric"><div class="micro">Addressed</div><div class="value">${addressed}</div><div class="trend">${state.reports.length?Math.round(addressed/state.reports.length*100):0}% of total</div></div><div class="metric"><div class="micro">Citizens</div><div class="value">${state.citizens.length}</div><div class="trend">Community signal</div></div></div><div class="content-grid"><section class="panel"><div class="panel-head"><h2 class="panel-title">Priority reports</h2><span class="micro">Sorted by severity</span></div>${reportRows(state.reports.slice(0,6),true)}</section><aside class="stack"><section class="panel"><div class="panel-head"><h2 class="panel-title">Resolution rate</h2><span class="micro">All reports</span></div><div class="value" style="font:600 50px 'Space Grotesk';letter-spacing:-.07em">${state.reports.length?Math.round(addressed/state.reports.length*100):0}%</div><div class="progress" style="margin:15px 0 11px"><i style="width:${state.reports.length?addressed/state.reports.length*100:0}%"></i></div><p class="muted">Keep the public loop short with timely updates.</p></section><section class="panel"><div class="panel-head"><h2 class="panel-title">Officer session</h2><span class="status addressed">Verified</span></div><p class="muted">PWD authority access is active for this review session.</p><button class="button ghost small" data-action="authority-logout">Sign out</button></section></aside></div>`, 'authority')}
function authorityReports(){const filtered=state.filters.status==='all'?state.reports:state.reports.filter(r=>r.status===state.filters.status);return layout(`${pagebar('Reports queue','Review, prioritize, and close incoming issues.')}<section class="panel"><div class="panel-head"><div class="segmented"><button class="${state.filters.status==='all'?'active':''}" data-filter="all">All</button><button class="${state.filters.status==='reported'?'active':''}" data-filter="reported">Open</button><button class="${state.filters.status==='addressed'?'active':''}" data-filter="addressed">Addressed</button></div><span class="micro">${filtered.length} tickets</span></div>${reportRows(filtered,true)}</section>`, 'authority')}
function citizensView(){return layout(`${pagebar('Citizen ledger','Community participation and reward activity.')}<section class="panel"><div class="panel-head"><h2 class="panel-title">Registered citizens</h2><span class="micro">${state.citizens.length} profiles</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Citizen</th><th>Contact</th><th>Reports</th><th>Impact points</th><th></th></tr></thead><tbody>${state.citizens.map(c=>`<tr><td><div class="profile-row"><img class="avatar" src="${mediaUrl(c.profile_pic_url)}" onerror="this.style.display='none'"/><div><strong>${esc(c.name||c.username)}</strong><span>@${esc(c.username)}</span></div></div></td><td>${esc(c.phone_number)}</td><td>${c.total_complaints}</td><td><strong>${c.total_rewards}</strong></td><td><button class="button ghost small" data-action="citizen" data-id="${c.id}">View ledger</button></td></tr>`).join('')}</tbody></table></div></section>`, 'authority')}
function analyticsView(){const total=state.reports.length,types={};state.reports.forEach(r=>types[r.damage_type]=(types[r.damage_type]||0)+1);return layout(`${pagebar('Analytics','Patterns in the public road signal.')}<div class="content-grid"><section class="panel"><div class="panel-head"><h2 class="panel-title">Issue mix</h2><span class="micro">${total} total reports</span></div><div class="stack">${Object.entries(types).sort((a,b)=>b[1]-a[1]).map(([key,val])=>`<div><div class="split"><strong>${esc(key)}</strong><span class="muted">${val} reports</span></div><div class="progress" style="margin-top:8px"><i style="width:${total?val/total*100:0}%"></i></div></div>`).join('')||'<div class="empty">No report data yet.</div>'}</div></section><section class="panel"><div class="panel-head"><h2 class="panel-title">Coverage view</h2><span class="micro">Approximate pins</span></div><div class="map-card"></div><p class="muted" style="margin:12px 0 0">Each report includes latitude and longitude for map integration.</p></section></div>`, 'authority')}
function render(){let html=state.view==='landing'?landing():state.view==='citizen'?citizenHome():state.view==='report'?reportForm():state.view==='track'?trackView():state.view==='authority'?(state.authority?authorityHome():authView('authority')):state.view==='reports'?authorityReports():state.view==='citizens'?citizensView():state.view==='auth'?authView(state.authRole):landing();$('#app').innerHTML=html;if(state.language==='manipuri'&&state.translations)applyTranslations();if(state.view==='report')setTimeout(requestLocation,150)}
async function refresh(){await loadReports();if(state.authority)state.citizens=await api('/api/citizens');render()}
function requestLocation(){if(!navigator.geolocation)return toast('Geolocation is not available. Enter coordinates manually.');navigator.geolocation.getCurrentPosition(pos=>{$('#location').value=`${pos.coords.latitude.toFixed(6)}, ${pos.coords.longitude.toFixed(6)}`;toast('Current location added.');},()=>toast('Location permission was not granted. You can enter coordinates manually.'),{enableHighAccuracy:true,timeout:10000})}
async function submitReport(){const [latitude,longitude]=$('#location').value.split(',').map(v=>Number(v.trim()));if(!Number.isFinite(latitude)||!Number.isFinite(longitude))return toast('Enter coordinates as latitude, longitude.');try{const report=await api('/api/reports',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({latitude,longitude,image_url:state.upload?.image_url||null,damage_type:$('#damage_type').value,severity_score:state.upload?.severity_score||0.5,description:$('#description').value,user_id:state.citizen.id})});toast(`Report #PWD-RR-${report.id} submitted. +50 impact points.`);state.citizen=await api(`/api/auth/users/${state.citizen.id}`);localStorage.setItem('rr_citizen',JSON.stringify(state.citizen));state.upload=null;state.view='track';await refresh()}catch(e){toast(e.message)}}
async function uploadFile(file){const fd=new FormData();fd.append('file',file);try{const data=await api('/api/upload',{method:'POST',body:fd});state.upload=data;$('#upload-preview').innerHTML=file.type.startsWith('image/')?`<img class="preview" src="${URL.createObjectURL(file)}" alt="Selected evidence"/>`:`<div class="notice" style="margin-top:14px">${esc(file.name)} ready for upload.</div>`;toast(`Evidence scanned: ${data.damage_type}, ${Math.round(data.confidence*100)}% confidence.`)}catch(e){toast(e.message)}}
async function authenticate(form){try{if(state.authRole==='authority'){if($('#auth-email').value==='officer@pwd.gov.in'&&$('#auth-password').value==='GovSecure#2026'&&($('#auth-badge').value==='PWD-MN-4091'||$('#auth-badge').value==='849201')){state.authority=true;state.view='authority';await refresh()}else toast('Use the demo authority credentials shown below.');return}if(state.authMode==='login'){state.citizen=await api('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:$('#auth-username').value,password:$('#auth-password').value})})}else{const phone=$('#auth-phone').value;await api('/api/auth/send-otp',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({phone_number:phone})});await api('/api/auth/verify-otp',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({phone_number:phone,otp:$('#auth-otp').value||'123456'})});state.citizen=await api('/api/auth/register',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({phone_number:phone,username:$('#auth-username').value,password:$('#auth-password').value,name:$('#auth-name').value})})}localStorage.setItem('rr_citizen',JSON.stringify(state.citizen));toast(`Signed in as ${state.citizen.name||state.citizen.username}.`);state.view='citizen';await refresh()}catch(e){toast(e.message)}}
async function openCitizen(id){try{const c=await api(`/api/citizens/${id}`);$('#app').insertAdjacentHTML('beforeend',`<div class="modal-backdrop" data-close-modal><section class="modal"><button class="modal-close" data-close-modal>${icon('close')}</button><div class="micro">Citizen profile</div><h2 class="panel-title" style="font-size:25px;margin:10px 0">${esc(c.name||c.username)}</h2><p class="muted">@${esc(c.username)} · ${esc(c.phone_number)}</p><div class="metric-grid" style="grid-template-columns:1fr 1fr"><div class="metric"><div class="micro">Reports</div><div class="value">${c.total_complaints}</div></div><div class="metric"><div class="micro">Points</div><div class="value">${c.total_rewards}</div></div></div>${reportRows(c.complaints)}</section></div>`)}catch(e){toast(e.message)}}
async function addressReport(id,nextStatus){try{await api(`/api/reports/${id}/status`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:nextStatus})});toast(nextStatus==='addressed'?'Report marked addressed.':'Report reopened.');await refresh()}catch(e){toast(e.message)}}
async function deleteReport(id){if(!confirm(`Delete request #PWD-RR-${id}? This cannot be undone.`))return;try{await api(`/api/reports/${id}`,{method:'DELETE'});toast('Request deleted.');await refresh()}catch(e){toast(e.message)}}
async function toggleLanguage(){try{if(state.language==='en'){if(!state.translations)state.translations=await api('/api/translations/manipuri');state.language='manipuri'}else state.language='en';render()}catch(e){toast(`Could not load Manipuri translations: ${e.message}`)}}
function applyTranslations(){const dict=state.translations||{};const walker=document.createTreeWalker($('#app'),NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);nodes.forEach(node=>{const raw=node.nodeValue;const trimmed=raw.trim();if(dict[trimmed])node.nodeValue=raw.replace(trimmed,dict[trimmed])})}
document.addEventListener('click',async e=>{const view=e.target.closest('[data-view]')?.dataset.view;if(view){if(view==='citizen'){state.authRole='citizen';state.view=state.citizen?'citizen':'auth'}else if(view==='authority'){state.authRole='authority';state.view=state.authority?'authority':'auth'}else state.view=view;if(view==='authority'&&state.authority)await refresh();else render();return}const authMode=e.target.closest('[data-auth-mode]')?.dataset.authMode;if(authMode){state.authMode=authMode;render();return}const action=e.target.closest('[data-action]')?.dataset;if(action?.action==='locate')return requestLocation();if(action?.action==='send-otp'){const phone=$('#auth-phone')?.value;if(!phone)return toast('Enter your mobile number first.');try{const r=await api('/api/auth/send-otp',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({phone_number:phone})});toast(`${r.message} Demo OTP: ${r.dummy_otp}`)}catch(err){toast(err.message)}return}if(action?.action==='address')return addressReport(action.id,'addressed');if(action?.action==='toggle-address'){const report=state.reports.find(r=>String(r.id)===String(action.id));return addressReport(action.id,report?.status==='addressed'?'reported':'addressed')}if(action?.action==='delete-report')return deleteReport(action.id);if(action?.action==='toggle-language')return toggleLanguage();if(action?.action==='citizen')return openCitizen(action.id);if(action?.action==='logout'){state.citizen=null;localStorage.removeItem('rr_citizen');state.view='landing';render();return}if(action?.action==='authority-logout'){state.authority=false;state.view='landing';render();return}if(action?.action==='detail'){const r=state.reports.find(x=>String(x.id)===String(action.id));if(r&&r.image_url)$('#app').insertAdjacentHTML('beforeend',`<div class="modal-backdrop" data-close-modal><section class="modal"><button class="modal-close" data-close-modal>${icon('close')}</button><div class="micro">Report evidence · #PWD-RR-${r.id}</div><h2 class="panel-title" style="margin:10px 0">${esc(r.damage_type)}</h2><img class="evidence-large" src="${mediaUrl(r.image_url)}" alt="Road evidence"/><p class="muted" style="margin:14px 0 0">${esc(r.description||'No description provided.')}</p></section></div>`);else if(r)toast(`#PWD-RR-${r.id}: ${r.status} · ${r.damage_type}`)}if(e.target.closest('[data-filter]')){state.filters.status=e.target.closest('[data-filter]').dataset.filter;render()}if(e.target.closest('[data-close-modal]')){const backdrop=e.target.closest('.modal-backdrop');if(backdrop)backdrop.remove()}else if(e.target.classList.contains('modal-backdrop'))e.target.remove()});document.addEventListener('change',e=>{if(e.target.id==='media'&&e.target.files[0])uploadFile(e.target.files[0])});document.addEventListener('submit',e=>{if(e.target.id==='report-form'){e.preventDefault();submitReport()}if(e.target.id==='auth-form'){e.preventDefault();authenticate(e.target)}});
(async function init(){try{await loadReports()}catch{}render()})();
